using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
[InitializeOnLoad] public static partial class EmergencyLightingWorkbench {
 public static readonly string[] Scenes={"Assets/Scenes/Emergency_Decon_Evaluation.unity","Assets/Scenes/Emergency_Decon_Tutorial.unity","Assets/Scenes/Emergency_Decon_Tutorial_Hand.unity"};
 const string Out="Temp/EmergencyLighting";
 static EmergencyLightingWorkbench(){EditorApplication.update+=Poll;Lightmapping.bakeCompleted+=BakeFinished;Application.logMessageReceived+=CaptureLog;}
 static void Poll(){if(finishAt>0&&EditorApplication.timeSinceStartup>=finishAt){finishAt=0;try{FinishCurrentScene();}catch(Exception e){Fail(e);}return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying||Lightmapping.isRunning||!File.Exists(Out+".request"))return;var cmd=File.ReadAllText(Out+".request").Trim();File.Delete(Out+".request");try{if(cmd=="glow")EnhanceFixtureGlow();else if(cmd=="shadows")EnhanceShadows();else if(cmd=="audit")Audit();else if(cmd=="diagnose")Diagnose();else if(cmd=="apply-evaluation")StartJob(0,0);else if(cmd=="apply-remaining")StartJob(1,2);else if(cmd=="apply-all")StartJob(0,2);else if(cmd=="render")Render(SceneManager.GetActiveScene(),"current");else throw new Exception("Unknown command "+cmd);}catch(Exception e){File.WriteAllText(Out+".error",e.ToString());Debug.LogException(e);}}
 static bool baking;static readonly List<string> bakeMessages=new List<string>();static string bakeLabel;
 static void CaptureLog(string message,string stack,LogType type){if(baking&&(message.Contains("Non finite")||message.Contains("invalid UV")||type==LogType.Exception||type==LogType.Error))bakeMessages.Add(message);}
 static void BakeFinished(){if(!baking)return;baking=false;File.WriteAllText(Out+"/"+bakeLabel+"-bake.txt","COMPLETE\n"+string.Join("\n",bakeMessages));if(jobIndex>=0){finishAt=EditorApplication.timeSinceStartup+1;return;}EditorSceneManager.SaveScene(SceneManager.GetActiveScene());}
 static void Diagnose(){var s=SceneManager.GetActiveScene();if(s.path!=Scenes[0]||EditorApplication.isPlaying)throw new Exception("Evaluation edit scene required");var changes=new List<string>();foreach(var r in All<MeshRenderer>(s)){if(Mathf.Abs(r.localToWorldMatrix.determinant)<1e-12f&&GameObjectUtility.AreStaticEditorFlagsSet(r.gameObject,StaticEditorFlags.ContributeGI)){GameObjectUtility.SetStaticEditorFlags(r.gameObject,GameObjectUtility.GetStaticEditorFlags(r.gameObject)&~StaticEditorFlags.ContributeGI);r.receiveGI=ReceiveGI.LightProbes;changes.Add(PathOf(r.transform));}}
 File.WriteAllText(Out+"/diagnose-changes.txt",string.Join("\n",changes));EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);bakeMessages.Clear();bakeLabel="zero-scale-excluded";baking=true;if(!Lightmapping.BakeAsync()){baking=false;throw new Exception("Bake did not start");}}
 [Serializable] class Report {public string active,lighting,pipeline,colorSpace;public bool dirty;public LightInfo[] lights;public Obj[] objects;public string[] badMeshes;public int probes,lightmaps;}
 [Serializable] class LightInfo {public string path,type,bake;public bool enabled;public Vector3 position;public Color color;public float intensity,range;}
 [Serializable] class Obj {public string path,mesh,asset,shader;public bool active,gi,uv2;public Vector3 position,scale,center,size;public int vertices,lightmapIndex;public float determinant;}
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 public static T[] All<T>(Scene s) where T:Component=>s.GetRootGameObjects().SelectMany(o=>o.GetComponentsInChildren<T>(true)).ToArray();
 static void Audit(){Directory.CreateDirectory(Out);var active=SceneManager.GetActiveScene();foreach(var path in Scenes){var s=SceneManager.GetSceneByPath(path);bool preview=!s.isLoaded;if(preview)s=EditorSceneManager.OpenPreviewScene(path);try{var bad=new List<string>();var checkedMeshes=new HashSet<Mesh>();var obs=new List<Obj>();foreach(var r in All<MeshRenderer>(s)){var mesh=r.GetComponent<MeshFilter>()?.sharedMesh;if(mesh==null)continue;var gi=GameObjectUtility.AreStaticEditorFlagsSet(r.gameObject,StaticEditorFlags.ContributeGI);obs.Add(new Obj{path=PathOf(r.transform),mesh=mesh.name,asset=AssetDatabase.GetAssetPath(mesh),shader=string.Join(",",r.sharedMaterials.Select(m=>m?m.shader.name:"MISSING")),active=r.enabled&&r.gameObject.activeInHierarchy,gi=gi,uv2=mesh.uv2.Length==mesh.vertexCount,vertices=mesh.vertexCount,position=r.transform.position,scale=r.transform.lossyScale,center=r.bounds.center,size=r.bounds.size,determinant=r.localToWorldMatrix.determinant,lightmapIndex=r.lightmapIndex});if(!checkedMeshes.Add(mesh))continue;var v=mesh.vertices;var n=mesh.normals;var uv=mesh.uv2;int nonfinite=v.Count(a=>!Finite(a.x)||!Finite(a.y)||!Finite(a.z))+n.Count(a=>!Finite(a.x)||!Finite(a.y)||!Finite(a.z));int zero=n.Count(a=>a.sqrMagnitude<1e-10f);if(nonfinite>0||zero>0)bad.Add(mesh.name+" nonfinite="+nonfinite+" zeroNormals="+zero);}
 var rep=new Report{active=s.path,dirty=s.isDirty,lighting=Lightmapping.lightingSettings?EditorJsonUtility.ToJson(Lightmapping.lightingSettings):"default",pipeline=GraphicsSettings.currentRenderPipeline?GraphicsSettings.currentRenderPipeline.name:"none",colorSpace=QualitySettings.activeColorSpace.ToString(),lights=All<Light>(s).Select(l=>new LightInfo{path=PathOf(l.transform),type=l.type.ToString(),bake=l.lightmapBakeType.ToString(),enabled=l.enabled&&l.gameObject.activeInHierarchy,position=l.transform.position,color=l.color,intensity=l.intensity,range=l.range}).ToArray(),objects=obs.ToArray(),badMeshes=bad.ToArray(),probes=All<LightProbeGroup>(s).Sum(g=>g.probePositions.Length),lightmaps=LightmapSettings.lightmaps.Length};File.WriteAllText(Out+"/"+s.name+"-audit.json",JsonUtility.ToJson(rep,true));if(!preview)Render(s,"before");}finally{if(preview)EditorSceneManager.ClosePreviewScene(s);}}File.WriteAllText(Out+".done","audit");}
 static bool Finite(float f)=>!float.IsNaN(f)&&!float.IsInfinity(f);
 static void Render(Scene s,string suffix){var go=new GameObject("Lighting review camera");go.hideFlags=HideFlags.HideAndDontSave;SceneManager.MoveGameObjectToScene(go,s);var cam=go.AddComponent<Camera>();cam.enabled=false;cam.scene=s;cam.transform.position=new Vector3(.5f,1.65f,1.8f);cam.transform.LookAt(new Vector3(.3f,1.1f,-2.7f));cam.fieldOfView=75;cam.nearClipPlane=.03f;cam.farClipPlane=50;cam.GetUniversalAdditionalCameraData().allowXRRendering=false;cam.GetUniversalAdditionalCameraData().renderPostProcessing=suffix.StartsWith("glow");cam.allowHDR=true;var rt=new RenderTexture(1600,1000,24,suffix.StartsWith("glow")?RenderTextureFormat.DefaultHDR:RenderTextureFormat.Default);rt.Create();var old=RenderTexture.active;var tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);try{RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1600,1000),0,0);if(suffix.StartsWith("glow")){var pixels=tex.GetPixels();for(int i=0;i<pixels.Length;i++)pixels[i]=pixels[i].gamma;tex.SetPixels(pixels);}tex.Apply();File.WriteAllBytes(Out+"/"+s.name+"-"+suffix+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
